#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Registro { std::string id, tipo; int bytes = 0; };
struct Admision { Registro registro; int primera; };
enum class Resultado { aceptado, formato, id, tipo, tamano };

bool letra(char c) { return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'); }
bool digito(char c) { return c >= '0' && c <= '9'; }
Resultado leer_registro(const std::string& linea, Registro& destino) {
    if (linea.size() > 80) return Resultado::formato;
    for (unsigned char c : linea)
        if (c != '\t' && (c < 32 || c > 126)) return Resultado::formato;
    std::istringstream flujo(linea);
    std::string id, tipo, texto, extra;
    if (!(flujo >> id >> tipo >> texto) || (flujo >> extra)) return Resultado::formato;
    if (id.size() > 12 || !letra(id[0])) return Resultado::id;
    for (char c : id) if (!letra(c) && !digito(c) && c != '_') return Resultado::id;
    if (tipo != "textura" && tipo != "malla" && tipo != "sonido") return Resultado::tipo;
    if (texto.empty() || texto.size() > 5) return Resultado::tamano;
    int bytes = 0;
    for (char c : texto) {
        if (!digito(c)) return Resultado::tamano;
        bytes = bytes * 10 + c - '0';
    }
    if (bytes < 1 || bytes > 30000) return Resultado::tamano;
    destino = {id, tipo, bytes};
    return Resultado::aceptado;
}
const char* nombre(Resultado r) {
    switch (r) {
        case Resultado::formato: return "FORMATO";
        case Resultado::id: return "ID";
        case Resultado::tipo: return "TIPO";
        case Resultado::tamano: return "TAMANO";
        default: return "ACEPTADO";
    }
}

